import{_ as t,o as c,c as r,a2 as e,j as d}from"./chunks/framework.xCjF2uVY.js";const s="/nds-site/video/demo_mori.mp4",b=JSON.parse('{"title":"进度 S0–S7","description":"八个阶段各自走到哪、判据是什么、还欠什么","frontmatter":{"title":"进度 S0–S7","description":"八个阶段各自走到哪、判据是什么、还欠什么"},"headers":[],"relativePath":"progress.md","filePath":"progress.md","lastUpdated":1791250821000}'),n={name:"progress.md"};function i(a,o,l,g,u,m){return c(),r("div",null,[...o[0]||(o[0]=[e('<h1 id="进度-s0–s7" tabindex="-1">进度：S0–S7 <a class="header-anchor" href="#进度-s0–s7" aria-label="Permalink to &quot;进度：S0–S7&quot;">​</a></h1><p>计划的终点是「一个房间可自由走动探索（裁剪版）」= <strong>静态场景 + 幻影加农本体 + Link 可行走</strong>。 下表左列是计划里写死的判据，右列是现在盘上站得住的读数 —— 每条都能在 <a href="/nds-site/acceptance.html">验收门读数</a> 里 找到对应的门，每张证据图都能在 <a href="/nds-site/gallery.html">画面证据</a> 里追溯到画它的那份 ROM。</p><table tabindex="0"><thead><tr><th>阶段</th><th>计划判据（原文口径）</th><th>状态</th><th>现在的读数</th></tr></thead><tbody><tr><td><strong>S0</strong> 资产完好 + 身份确认</td><td><code>asset_verify.py</code> 全绿；角色 ROM md5 逐位不变；actor <code>0x52</code> → object ID → object 文件三者钉死</td><td>✅</td><td><code>object:378/0 other:539/1 room:388/0 scene:101/0 static:102/0</code>（dmadata 那条是良性例外）；本体 = <code>object_gnd</code>，Standard 骨架</td></tr><tr><td><strong>S1</strong> 房间 DL → JSON</td><td>逐位复现 694/408、1061/610；<code>G_MTX==0</code>；<code>Σn==unique</code>；母 DL 每条子 DL 的 tri 之和 == 房间总 tri</td><td>✅</td><td><code>room_reconcile.py</code> <strong>32/32</strong>：room_0 694 顶点/408 三角形、room_1 1061/610（opa 608 + xlu 2），两间 <code>G_MTX==0</code>，索引口径 ×2 胜，纹理字节守恒</td></tr><tr><td><strong>S2</strong> 房间纹理烘焙</td><td>纹理总和 ≤ 256 KB；TLUT 数量与 <code>LOADTLUT</code> 计数一致；<code>w*h</code>/<code>lrs+1</code>/<code>dxt</code> 互洽</td><td>✅</td><td>预算门 <strong>13/13</strong>（room_0 13,312 B、room_1 32,512 B）；机内 <code>VRAMMAP=1</code> 实测 22 段 / 66 KB / 零重叠</td></tr><tr><td><strong>S3</strong> 静态场景 ROM</td><td>GPU 读数 == S1 JSON 读数（无丢包）</td><td>✅</td><td>三个机位的 OCR 读数 <code>GPU 1018/1018</code>、<code>verts 1755 tex 22</code>、<code>BOSS 440/440</code>、<code>entry floor -193</code> 与离线现算期望值逐位相同</td></tr><tr><td><strong>S4</strong> 透视相机 + 组剔除</td><td>各 yaw 下可见组与离线 bbox 预测一致；<code>fovy=60°</code>/<code>zFar=1500</code>/<code>fogNear=940</code></td><td>✅</td><td>13 机位逐个过 <code>actual ⊆ predicted</code>；九台剔除孪生主屏 <strong>AE=0</strong>；环境参数四段（ROM 现解 == 头文件 == <code>main.c</code> 字面量 == 量具 <code>--bg</code>）一致</td></tr><tr><td><strong>S5</strong> 碰撞 + 行走</td><td><code>feet_y</code> 常量断言；推向边界被拒坐标与 COL min/max 一致</td><td>✅</td><td>行走预测器自验 FAIL 行 0；四条拒绝分支的<strong>被拒停点设备 == 离线仿真</strong>逐位相同（(15,−3626)/(−760,−2979)/(63,−2904)/(−45,−2904)）</td></tr><tr><td><strong>S5</strong> Link 剪影（走到位的机位）</td><td>— 计划里没有，本轮加的</td><td>✅</td><td>两台机位 CPU 填充 vs 实机差渲染：实机 1598 / 1656 px，位后 IoU <strong>0.878 / 0.906</strong>，一圈 100.0/100.0（这一行<strong>不判绝对摆放</strong>，相机绕玩家 orbit 是它的规范自由度）</td></tr><tr><td><strong>偏差 2</strong> Link 角色纹理</td><td>— 计划里没有，是验收图看出来的缺陷</td><td>✅</td><td><code>src_scene/link_rigid.c</code> 的 <code>LINKTEX</code> 默认值 <strong>1</strong>（2026-10-08 转正）；验收 ROM <code>83bd4dfa</code> 里林克有真纹理。同机位与翻转前的锚点 <code>dd9bfa50</code> 逐像素比差 <strong>530 px</strong>，差异 bbox x112–149 / y149–191 正好是 Link 的剪影 ⇒ 房间与本体没被带动</td></tr><tr><td><strong>S6</strong> Boss 本体静态网格</td><td>竞技场里看得见幻影加农本体</td><td>✅</td><td>699 顶点/440 三角形解出；剪影门两台位后 IoU <strong>0.801 / 0.796</strong>、最优位移都是 dx=2 在带内；深度归属门近机位 <strong>Link 挡住本体 166 px、本体画进 Link 剪影内 0 px</strong>（<code>--maxover 0</code> 照样 PASS）</td></tr><tr><td><strong>S6</strong> xlu 半透明层</td><td>— 计划里只说&quot;近似&quot;</td><td>⚠ 量到极限</td><td><code>dose</code> 8523 px 100% 落在离线 footprint 内、位后 IoU 0.902（几何归因成立）；深度那侧<strong>共面 ⇒ 平局不可判</strong>（离线距离差 1.71 raw，而 DS 深度一格是 4 raw）</td></tr><tr><td><strong>S7</strong> 运行时 FK（可选项）</td><td>走路姿势随四肢变化</td><td>➖ 不需要</td><td>本体是 Standard 骨架（S0 的结论），FK 不在本场景依赖里</td></tr></tbody></table><h2 id="还欠什么" tabindex="-1">还欠什么 <a class="header-anchor" href="#还欠什么" aria-label="Permalink to &quot;还欠什么&quot;">​</a></h2><ol><li><strong>人眼判决（协议 3）没收到</strong>。数字门全部通过后，&quot;这就是森林 boss 房、纹理是对的、比例是对的&quot;这一句 必须由人看图判定，量具不代替它。素材在 <a href="/nds-site/gallery.html">画面证据</a> 的前两节（验收 ROM 三张 + 七张拼图）， 其中 <code>contact_sheet_2026-10-05_final.png</code> 是<strong>终检图</strong>：四格各只问一件事（整场景 / 本体被 Link 挡住 像不像 / 走到位后比例与四肢 / 转的是相机不是重画场景），一票判完不必翻其余六张分项。</li><li><strong>偏差 4 会被人看见</strong>：本轮按计划不做相机碰撞，房间小、<code>CAM_DIST=90</code> 而眼高只有 60 ⇒ 5975 个合法站立格里 四个朝向各有 <strong>50~55%</strong> 让眼点落进极近几何档，那个档里量具与真机对不齐（色场 WARN 的来源）。</li><li><strong>偏差 1 的归属未证</strong>：desmume 相对 CPU 量具的屏幕错位<strong>不是恒定 +3px</strong>（y180 最优是 dx=0）， 本体那四个独立读数倒是都落在 dx=2。<code>glGetFixed</code> 回读在 desmume 上不响应 ⇒ 上真机第一件事就是复测这条。</li><li><strong>本体角色纹理仍以决定为由关掉</strong>：<code>draw_boss.c</code> 只走顶点色 + 白纹理单位元，所以幻影加农在画面里发白。 <code>object_gnd</code> 的骨架可达 limb DL 里实测有 51 SETTIMG / 51 LOADBLOCK / 51 SETTILESIZE / 102 SETTILE / 52 SETCOMBINE （且这是下界：每条 limb DL 那条外部段 <code>G_DL</code> 按既有口径不递归），要补得走与房间同套管线的另一份口径。 Link 那侧<strong>已经不在这一条里了</strong>：<code>src_scene/link_rigid.c</code> 的 <code>LINKTEX</code> 默认值为 1（2026-10-08 转正，见下面那节）， 验收 ROM 里的林克带真纹理。两条的完整口径与实测数在 <a href="/nds-site/caveats.html">已知偏差</a> 偏差 2。 ⚠ 本页此前抄的是「190 / 97 / 54」，那是整镜像朴素 opcode 直方图把数据字节数成命令的结果，已由 docs §5 更正。</li><li><strong>偏差 5 也会被人看见</strong>：把 Link 走到竞技场沿上，他<strong>站住不动而不是掉下去</strong> —— 本轮不做重力，落点的地板 探测窗口是 <code>[feetY, feetY+6]</code>（<code>src_scene/main.c:605</code>，下界正好等于当前脚底），所以任何比当前脚底低的地面 一律被拒、整次移动作废。计划 S5 只要求&quot;站在地面、撞墙不穿&quot;，没要求 fall 状态，所以这是裁剪口径而不是 地板解漏了多边形。图上认这条看的是副屏<strong>坐标数字停住、<code>walk</code> 那对极值不再扩大</strong>，不是状态词 —— 截图前必然松键， 而 <code>moveState</code> 每帧在按键检查前复位，存档图里那个词恒为 <code>idle</code>（<code>[feetY, feetY+6]</code> 这条窗口的实测范围与配方在 <a href="/nds-site/caveats.html">已知偏差</a> 偏差 5）。</li></ol><h2 id="一句话现状" tabindex="-1">一句话现状 <a class="header-anchor" href="#一句话现状" aria-label="Permalink to &quot;一句话现状&quot;">​</a></h2><p>八阶段全部有数字门通过，<code>--rebuild</code> 90 项(其中 50 台 ROM 逐位复现；本轮唯一未闭合的是&quot;人看图说它是&quot;这件事， 以及偏差清单里那几条被明确记为<strong>范围决定 / 量具极限</strong>的差距（见 <a href="/nds-site/caveats.html">已知偏差</a>）。</p><h2 id="演示录屏-2026-10-06" tabindex="-1">演示录屏（2026-10-06） <a class="header-anchor" href="#演示录屏-2026-10-06" aria-label="Permalink to &quot;演示录屏（2026-10-06）&quot;">​</a></h2><p>ROM 自己演，不用手按：<code>DEMO=1</code> 每帧<strong>合成</strong>一个按键掩码喂给同一条行走/相机链（<code>src_scene/main.c</code> 的 <code>s_demo[]</code> 剧本：走进竞技场 → 相机转 180° → 再前进 → 回转 270° → 抬头 → 压低看本体 → 原路退回， 循环）。注入点在 START 退出判据之后，所以<strong>你碰任意键它就让出控制权</strong>，演示不是第二条没人验过的代码， 走的位置由同一份碰撞与同一步长决定。</p>',9),d("p",null,[d("video",{src:s,controls:"",autoplay:"",muted:"",loop:"",playsinline:"",preload:"metadata",style:{width:"100%","max-width":"640px",display:"block",border:"1px solid var(--vp-c-divider)"}})],-1),e('<ul><li>录屏 ROM：<code>demoMori.nds</code> = <code>a583e3a0</code>，配方 <code>make -s SCENE=moribossroom WALK=1 BOSS=1 STARTX=15 STARTZ=-2900 CAMYAW=0.0 CAMPITCH=-5.0 DEMO=1 LINKTEX=1 NAME=demoMori</code>（60 fps 口径；无头 desmume 开 <code>--disable-limiter</code> 会比这个快）。</li><li>录屏由<strong>单个</strong> desmume 实例连续抓 30 帧拼成（相邻帧间变化 31k~46k / 49152 px，29 对里没有一对静止 ⇒ 确实在动，不是同一张图重复）。格式是 <strong>MP4（397 KB）</strong>——屏幕录制一律用 mp4，不用 gif：同一份画面 gif 要 2 MB，还拖不动进度条。</li><li>这台同时带 <code>LINKTEX=1</code>，所以下面那条 Link 纹理的修复在录屏里是看得见的。</li><li>⚠ 它<strong>不在</strong>逐位复现名单里，所以&quot;这台演示 ROM 的字节&quot;目前是一次性实测；要不要扩门进去，等你点头。</li></ul><h2 id="进度记录-2026-10-06-link-纹理链落地那一轮" tabindex="-1">进度记录 2026-10-06（Link 纹理链落地那一轮） <a class="header-anchor" href="#进度记录-2026-10-06-link-纹理链落地那一轮" aria-label="Permalink to &quot;进度记录 2026-10-06（Link 纹理链落地那一轮）&quot;">​</a></h2><ul><li><strong>Link 在场景 ROM 里本来就没有纹理</strong>（2026-10-06 发现并修）：<code>src_scene/link_rigid.c</code> 整条路只绑 白纹理单位元 + 逐部位纯色，一次 <code>glTexCoord2f</code> 都没发 —— 而 <code>include/link_tex_groups.h</code> 里每组的 <code>tex_id</code> 与每顶点的 UV 一直都有，只是没人用（独立 ROM <code>src/link_full_render.c</code> 用的是完整那条链， 所以&quot;林克有纹理&quot;在旧交付里成立、在场景 ROM 里不成立）。新旋钮 <code>LINKTEX=1</code> 接上：上传 17 张 RGBA （与 <code>texInfos[]</code> <strong>同序</strong>，那是 <code>tex_id</code> 的编号契约）、<strong>逐组</strong>绑定（房间那条路的教训是整条 DL 只绑 一次会让后半段拿前半段的纹理）、纯色组继续走白纹理、逐顶点发 UV、<code>glPolyFmt</code> 加 <code>POLY_MODULATION</code>。 实测 <code>lkSceneTex.nds</code> = <code>83bd4dfa</code>：同机位与锚点逐像素比<strong>差 530 px，差异 bbox x112–149 / y149–191</strong> —— 正好是 Link 的剪影，房间与本体一个像素没动；<code>LINKTEX</code> 不传时锚点重编仍是 <code>dd9bfa50</code>。 交付 ROM 默认<strong>没开</strong>它（开了就是换验收实物），要不要转正等你决定。 —— 这一句在 2026-10-08 过期：用户点头转正，锚点因此从 <code>dd9bfa50</code> 换成 <code>83bd4dfa</code>，细节见下一节。</li><li><strong>眼包素材的一处缺陷</strong>：偏差清单以前只记了「本体无纹理是范围决定」，<strong>没记「场景里的 Link 无纹理」</strong>， 画廊的&quot;不算缺陷&quot;列表里也没有 —— 于是看图的人只能得出&quot;该有纹理的地方是糊的&quot;。这条已经落到唯一上游： <code>docs/scene-port.md</code> §5 偏差 2 现在同时写明两处角色纹理的状态，<a href="/nds-site/caveats.html">已知偏差</a> 那页由它再生。</li><li><strong>眼包自己的血统规矩补齐</strong>：<code>_persp</code> 前三格背后的三台变体 ROM（<code>lkTexW b68af78a</code> / <code>lkTexFar 7f6c5831</code> / <code>lkBxFar d8e6f4d3</code>）此前从没按现源码逐位复现过 —— 按&quot;每张图的前缀必须能用当前源码逐位复现&quot;这条规矩， 那三格当时不算验收 ROM 的证据。今天整套照抄旋钮、逐台 <code>rm -rf build/&lt;NAME&gt;</code> 重编，三台<strong>全部逐位相同</strong>； <code>lkBxFar</code> 另做了 <code>LINKDRAW=0/1</code> 双产物交叉验证（第二次正好命中在册预测的 <code>bde1a5a1</code>），说明重建出的旋钮 集合唯一，不是碰巧对上。命令与结果逐字记在 <code>evidence/eye/manifest.txt</code>。这三台<strong>不在</strong>逐位复现名单里， 把它们加进去属于扩门，留给用户点头。 —— 2026-10-08 更正：那三台里 <strong><code>lkBxFar</code> 今天按两份 manifest 记录的任一旋钮集合都编不出在册的 <code>d8e6f4d3</code></strong>， 而且 <code>evidence/eye/</code> 与 <code>evidence/uvfix/</code> 两处对同一台记录的 <code>LINKDRAW</code> 取值互相矛盾。血统问题记在下面 10-08 那节。</li><li><strong>发布面 == 在册实物</strong>：线上 8 张拼图逐张与 <code>evidence/eye/</code> 里的同名文件比字节，<strong>8/8 相同</strong>。这是&quot;你可以 直接在页面上投票&quot;的前提 —— 你看到的画面就是被复现过的那份 ROM 画出来的。第一遍有一张取回 0 字节（网络侧 偶发，重取即 200 且 md5 一致），别读成&quot;线上缺图&quot;。</li><li><strong>判读口径改了两处，都是&quot;别让评审人投出假 FAIL&quot;</strong>：<code>_persp</code>/终检里&quot;本体没有纹理&quot;是本轮的范围决定而不是缺陷 （<code>src_scene/boss</code> 那条链路只走顶点色）；终检第 1 格原写&quot;整场景对不对&quot;，但实测那个机位下入口房<strong>在相机背后</strong> （离线量具印它 0 px，而竞技场那间 49143 px），副屏那栏 <code>GPU 1018/1018</code> 是&quot;两间全量提交、未剔除&quot;，不等于 &quot;两间都看得见&quot;。</li><li><strong>仍然没闭合的只有一件事</strong>：协议 3 的人眼判决。机器侧四条协议都有当轮实测，但&quot;这就是森林 boss 房&quot;这句话 不能由量具自己说。另有两项等你决定：<code>tools/measure_walk.sh</code>/<code>measure_fps.sh</code> 是删掉还是给 ROM 加一条机器 可读输出通道（现 emulator 不转发宿主 printf），以及上面那句扩门。</li></ul><h2 id="进度记录-2026-10-08-linktex-转正-改一行默认值-换整个验收实物" tabindex="-1">进度记录 2026-10-08（<code>LINKTEX</code> 转正：改一行默认值，换整个验收实物） <a class="header-anchor" href="#进度记录-2026-10-08-linktex-转正-改一行默认值-换整个验收实物" aria-label="Permalink to &quot;进度记录 2026-10-08（`LINKTEX` 转正：改一行默认值，换整个验收实物）&quot;">​</a></h2><ul><li><strong>源码侧只改一行</strong>：<code>src_scene/link_rigid.c</code> 里 <code>LINKTEX</code> 的默认值 0 → 1，树里没有第二处改动。验收锚点因此 <code>dd9bfa50</code> → <strong><code>83bd4dfa</code></strong>。锚的链条：<code>66fb25a5</code>（纹理修复前）→ <code>dd9bfa50</code>（旋钮落地但默认 0）→ <code>83bd4dfa</code>。</li><li><strong>重锚不是改文件名，是把画面重拍一遍</strong>：<code>tools/reanchor.py</code> 按&quot;配方 → 构建 → 截图&quot;三段走，67 台在册配方逐台 <code>rm -rf build/&lt;NAME&gt;</code> 重编（<strong>这句里的 <code>rm -rf</code> 是流程本身要求的</strong>，不清 build 目录会得到上一台的二进制）， 结果 <strong>66 台 ROM 变了、1 台没变</strong>。没变的那台是 <code>lkG270f</code>（<code>BOSS=0 LINKDRAW=0 ROOMTEX=0</code> 的纯透视探针，画面里 根本没有 Link）—— 这正好是&quot;翻动只作用在画林克的那批构建上&quot;的反证。8 张拼图随之全部重出。</li><li><strong>键控截图那几张不能原样重拍</strong>：手按出来的停点不是可复现位姿，换锚后拍不出同名同物的图。三条走位判据改用 编译期孪生钉在同样的读数上（<code>lkWalk303060 87808691</code> / <code>lkWp600300 481e34b5</code> / <code>lkWyr600300 462551c2</code>， <code>tools/walk_pose_proof.sh</code> 要求差渲染 0/49152），旧的键控图移进 <code>evidence/eye/stale/</code> 而不是删掉。</li><li><strong>门读数一个都没被这次翻动改变</strong>：三个机位 <code>GPU 1018/1018</code> / <code>verts 1755 tex 22</code> / <code>BOSS 440/440</code> / <code>entry -193</code> 原样； 本体剪影位后 IoU <code>0.801 / 0.796</code>（最优位移都 dx=2）；深度归属近机位遮挡 166 px、<strong>本体画进 Link 剪影内 0 px</strong>； xlu <code>dose 8523 / 交付净 689 / 位后 IoU 0.902</code>；Link 剪影 <code>预测 1663 / 实机 1598</code>。纹理是着色层的事，不动几何 —— 这正是本轮要的等价性证据：换了实物，没换结论。</li><li><strong>一处血统没闭合</strong>：<code>lkBxFar</code> 在册的 <code>d8e6f4d3</code> 今天编不出来。两份 manifest 各记了一套旋钮，分别重编得到 <code>38198476</code> 和 <code>58b24637</code>，都对不上在册值；而 <code>evidence/eye/manifest.txt</code> 与 <code>evidence/uvfix/manifest.txt</code> 对同一台 写的 <code>LINKDRAW</code> 取值<strong>正好相反</strong>。这条按日期写成了两份 manifest 里的更正，没有替它编一个说法。同批复核里 <code>lkTexW</code>/<code>lkTexFar</code> 重编成 <code>85ce1db0</code>/<code>507db893</code>（像素与旧归档逐位相同，因为它们在册配方里 <code>LINKDRAW=0</code>）。</li><li><strong>无旋钮的默认构建现在是 <code>c8fee40d</code></strong>（上一轮这个位置是 <code>9ac35a04</code>）。⚠ 它<strong>原地覆盖</strong>同名 ROM，所以&quot;锚点 = 默认构建产物&quot;这件事只能靠 <code>NAME=</code> 和逐位复现名单守；<code>NAME=</code> 本身不改一个字节。整树 <code>build/</code> 清空后重编， <code>83bd4dfa</code> 与 <code>8a546db4</code> 两个锚点逐位复现（<code>scripts/recheck_1008.sh</code>）。</li><li><strong>两处工具路径被重命名打断</strong>（说明&quot;改名&quot;这一步的波及面比文件名大）：<code>tools/boss_frame_gate.py</code> 的 <code>STATIC_TWIN</code> 还指着旧名 <code>7996fa4a_lkBoss_y0p-5_top.png</code>，S8f 门直接 <code>FileNotFoundError</code>；站点画廊 <code>GALLERY</code> 也整片指着换锚前的 文件名，被&quot;站点画廊可读性&quot;那条门拦下。两处都随锚点重挂，生成页与 <code>index.md</code> 首图重出。</li><li><strong>顺带把一条&quot;机内读回&quot;类证据重测了</strong>：<code>evidence/vrammap</code> 那句&quot;22 张就是全部、场景 ROM 里 Link 不占纹理显存&quot; 是纹理转正前的实物画的，翻默认值就过期了（文件名与前缀会响，读数过期是哑的）。给 <code>linkVramMap()</code> 补了同口径的 Link 侧实测(<code>#if VRAMMAP &amp;&amp; WALK</code>，没传旋钮不编译，两枚锚点重编仍 <code>83bd4dfa</code> / <code>8a546db4</code>)，今天的读数是 <strong>房间 22 段 / 66 KB + Link 17 段 / 22 KB，两批首尾相接零重叠、合计水位 89 KB(池子 256 KB 的 34.8%)</strong>。</li></ul><h2 id="进度记录-2026-10-08-持剑变体-把-剑在手里-从数量对账搬到像素上" tabindex="-1">进度记录 2026-10-08（持剑变体：把&quot;剑在手里&quot;从数量对账搬到像素上） <a class="header-anchor" href="#进度记录-2026-10-08-持剑变体-把-剑在手里-从数量对账搬到像素上" aria-label="Permalink to &quot;进度记录 2026-10-08（持剑变体：把&quot;剑在手里&quot;从数量对账搬到像素上）&quot;">​</a></h2><ul><li><strong><code>LINKSWORD=1</code> 换的是一条 limb 的显示列表，不是加一条 limb</strong>（默认 <strong>0</strong>）。ROM 运行时干的就是这件事 （<code>z_player.c</code> 改 <code>LinkSharedPointer</code> 的 <code>dList</code>），网格与道具跑在同一条骨头矩阵下，所以 <code>gLinkChildLeftHandHoldingMasterSwordDL</code>(@0x15540) 接进来后顶点 624→733、三角 697→763 只证明&quot;多出来的 东西进来了&quot;，不证明&quot;它长在该长的地方&quot;。验收落在像素上：同一机位、同一台机器、<code>ROOMS=0</code> 洋红底， 差集 <code>持剑 XOR 无剑</code> = <strong>正对机位新增 426 px / 侧机位新增 425 px，丢失 0 px</strong>。&quot;丢失 0&quot;是最要紧的一格： 只换 L_HAND，其余 17 条 limb 逐位不动 ⇒ 屏幕上不该有原本属于 Link 的像素消失。3D 侧另有一组接地数： 柄/护手/徽记三片壳离手心最近点 <strong>0.114 / 0.114 / 0.140</strong>（一个像素约 0.057 单位），刀刃从手的前缘伸出去 2.73 个模型单位。归属不变量在变体上一字不差（73 / 143 / 144），剔背面 611→677、双面 86 不变。</li><li><strong>抓到第一件事：道具把整只林克平移了半个身位，而数量对账看不见它。</strong> <code>GLOBAL_OFF</code> 是&quot;把模型 bbox 中心 摆到视口中心&quot;的显示参数，bbox 从当前资产算 ⇒ 加剑后整只模型被推走 (-0.30, 0, +0.85) 个世界单位，身体 离开 <code>STARTX/STARTZ</code> 那个站位，而逐 limb 的顶点数与三角形数一个都没变、对账全绿。修法不是给变体配一套偏移，而是新增 <code>--center-from=&lt;json&gt;</code> 让变体拿<strong>基线</strong>算中心；修完在盘上验：前 428 个顶点与基线最大位移 <strong>0.0</strong>。</li><li><strong>抓到第二件事：量具的机位能把同一件事量成十分之一。</strong> 近机位(<code>CAMPITCH=-5</code>)量出&quot;持剑只多 27~29 px&quot;， 第一反应是&quot;剑被剔掉了&quot;，加 <code>LINKCULL=0</code> 重测两台读数<strong>一字不变</strong>(1141 vs 1141) ⇒ 不是剔除；真因是那台 机位下下半身本来就在屏外（前景 bbox 下沿 = 191 = 屏幕最后一行），剑长在腰高，量的是被裁剩的半截。 换到全身入画的 <code>CAMPITCH=9.0</code> 后同一件事是 425 px。那两张近机位图留作<strong>反面样本</strong>，不作判据 —— 这正是 &quot;前景 bbox 不得贴屏幕边界&quot;这条守卫存在的原因。</li><li><strong>站点侧跟着证据重排</strong>：画廊多了&quot;持剑变体&quot;一节（四张判据图 + 差集掩膜 + 反面样本），<code>evidence/linksil/</code> 那批<strong>重拍了一遍</strong> —— 不是画面错了，是它们的身份证错了：PNG 文件名前缀本该是<strong>画它那份 ROM</strong> 的整文件 md5，<code>_sub.png</code> 那几张却按图片自己的 md5 命名的。<code>evidence_audit</code> 判据 A 两种都认，所以门一直是绿的， 这类不一致是哑的。重拍后逐条复核了在册不变量（1598/1656、IoU 0.878/0.906、两台 <code>off</code> 图与 sub 图 逐字节相同），旧图移进 <code>stale/</code> 而不是删掉。</li><li><strong>发布面收成一个目的地</strong>：Qoder Site 已删除，站只上 GitHub Pages（<code>/nds-site/</code> 子路径）。逐字节复现名单 从 47 台加到 <strong>50 台</strong>（持剑三台孪生先证再锚：每台 <code>rm -rf build/&lt;NAME&gt;</code> 连编两遍、两遍逐字节相同才写 md5），<code>--rebuild</code> 因此 <strong>87 项 → 90 项</strong>。这次翻动的真正收益是门自己抓到了两处过期声明（docs §4 与 站点手抄都还写着 87），&quot;扩门不改声明就 FAIL&quot;这条链条实测有效。</li></ul>',7)])])}const q=t(n,[["render",i]]);export{b as __pageData,q as default};
